CREATE DATABASE IF NOT EXISTS ai_campus_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ai_campus_portal;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','recruiter','tpo','admin') NOT NULL, status ENUM('pending','active','inactive','suspended') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_users_role_status(role,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, phone VARCHAR(30) NULL, branch VARCHAR(120) NULL, degree VARCHAR(120) NULL, semester TINYINT UNSIGNED NULL, cgpa DECIMAL(4,2) NULL, graduation_year SMALLINT UNSIGNED NULL, bio TEXT NULL, interests JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_student_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT chk_student_cgpa CHECK(cgpa IS NULL OR (cgpa>=0 AND cgpa<=10))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, category VARCHAR(80) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_skills (student_id BIGINT UNSIGNED NOT NULL, skill_id BIGINT UNSIGNED NOT NULL, proficiency ENUM('beginner','intermediate','advanced') NOT NULL DEFAULT 'beginner', verified TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY(student_id,skill_id), FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_certifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, issuer VARCHAR(180) NULL, issued_on DATE NULL, credential_url VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NULL, project_url VARCHAR(500) NULL, skills_json JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resumes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL UNIQUE, mime_type VARCHAR(100) NOT NULL, file_size INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS companies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, website VARCHAR(255) NULL, industry VARCHAR(120) NULL, description TEXT NULL, approval_status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_company_approval(approval_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recruiter_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, company_id BIGINT UNSIGNED NULL, designation VARCHAR(120) NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, location VARCHAR(180) NULL, employment_type VARCHAR(80) NULL, min_cgpa DECIMAL(4,2) NOT NULL DEFAULT 0, eligible_branch VARCHAR(120) NULL, graduation_year SMALLINT UNSIGNED NULL, status ENUM('draft','published','paused','closed') NOT NULL DEFAULT 'draft', closes_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, INDEX idx_jobs_status_closes(status,closes_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS job_skills (job_id BIGINT UNSIGNED NOT NULL, skill_id BIGINT UNSIGNED NOT NULL, requirement_type ENUM('required','preferred') NOT NULL DEFAULT 'required', PRIMARY KEY(job_id,skill_id), FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS job_eligibility_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id BIGINT UNSIGNED NOT NULL, rule_type VARCHAR(60) NOT NULL, rule_value VARCHAR(255) NOT NULL, mandatory TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, status ENUM('submitted','under_review','shortlisted','interview','selected','rejected','withdrawn') NOT NULL DEFAULT 'submitted', cover_note TEXT NULL, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_job_student(job_id,student_id), INDEX idx_app_status(status), FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE RESTRICT, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS application_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, changed_by BIGINT UNSIGNED NOT NULL, old_status VARCHAR(30) NULL, new_status VARCHAR(30) NOT NULL, note VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE, FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assessments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT NULL, status ENUM('draft','published','closed') NOT NULL DEFAULT 'draft', created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assessment_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assessment_id BIGINT UNSIGNED NOT NULL, question TEXT NOT NULL, options_json JSON NULL, correct_answer VARCHAR(255) NULL, points DECIMAL(6,2) NOT NULL DEFAULT 1, FOREIGN KEY(assessment_id) REFERENCES assessments(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assessment_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assessment_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, score DECIMAL(8,2) NULL, started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, submitted_at DATETIME NULL, FOREIGN KEY(assessment_id) REFERENCES assessments(id) ON DELETE RESTRICT, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assessment_answers (attempt_id BIGINT UNSIGNED NOT NULL, question_id BIGINT UNSIGNED NOT NULL, answer TEXT NULL, is_correct TINYINT(1) NULL, points_awarded DECIMAL(6,2) NULL, PRIMARY KEY(attempt_id,question_id), FOREIGN KEY(attempt_id) REFERENCES assessment_attempts(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES assessment_questions(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS interviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, scheduled_by BIGINT UNSIGNED NOT NULL, scheduled_at DATETIME NOT NULL, mode VARCHAR(60) NULL, location_or_link VARCHAR(500) NULL, status ENUM('scheduled','completed','cancelled','rescheduled') NOT NULL DEFAULT 'scheduled', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE, FOREIGN KEY(scheduled_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS interview_feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, interview_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, rating TINYINT UNSIGNED NULL, feedback TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(interview_id) REFERENCES interviews(id) ON DELETE CASCADE, FOREIGN KEY(reviewer_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS career_fit_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, job_id BIGINT UNSIGNED NOT NULL, fit_score DECIMAL(5,2) NOT NULL, components_json JSON NOT NULL, computed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE, INDEX idx_fit_lookup(student_id,job_id,computed_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_gap_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, job_id BIGINT UNSIGNED NOT NULL, missing_skills_json JSON NOT NULL, computed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS learning_roadmaps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, job_id BIGINT UNSIGNED NULL, title VARCHAR(180) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roadmap_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, roadmap_id BIGINT UNSIGNED NOT NULL, skill VARCHAR(100) NOT NULL, priority ENUM('Low','Medium','High') NOT NULL DEFAULT 'Medium', practice_task TEXT NULL, project_idea TEXT NULL, estimated_hours SMALLINT UNSIGNED NULL, status ENUM('not_started','in_progress','completed') NOT NULL DEFAULT 'not_started', sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(roadmap_id) REFERENCES learning_roadmaps(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_notification_user_read(user_id,read_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, author_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, audience ENUM('all','students','recruiters','tpo') NOT NULL DEFAULT 'all', published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NULL, entity_id BIGINT UNSIGNED NULL, ip_hash CHAR(64) NULL, metadata_json JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_audit_action_created(action,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(120) PRIMARY KEY, setting_value TEXT NOT NULL, updated_by BIGINT UNSIGNED NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
